// DFA accept states array
var dfaAcceptStatesDFAAlternation = [15]bool{false, false, false, false, false, false, false, false, false, false, false, false, true, false, false}

// DFA accept states array (End of Text)
var dfaAcceptStatesEOTDFAAlternation = [15]bool{false, false, false, false, false, false, false, false, false, false, false, false, true, false, false}

func (DFAAlternation) MatchString(input string) bool {
	inputLen := len(input)

	// Try each start position (O(n²) worst case for unanchored patterns)
	for start := 0; start <= inputLen; start++ {
		var state int
		if start == 0 {
			state = 0
		} else {
			state = 0
		}

		// Check if start state accepts (empty match)
		if dfaAcceptStatesDFAAlternation[state] {
			return true
		}
		// Check EOT acceptance at empty position
		if start == inputLen && dfaAcceptStatesEOTDFAAlternation[state] {
			return true
		}

		// Process input characters
		for i := start; i < inputLen; i++ {
			c := input[i]
			if c >= 128 {
				break
			}

			nextState := dfaTransitionsDFAAlternation[state][c]
			if nextState < 0 {
				break
			}

			state = nextState
			if dfaAcceptStatesDFAAlternation[state] {
				return true
			}
			// Check EOT acceptance at last character
			if i == inputLen-1 && dfaAcceptStatesEOTDFAAlternation[state] {
				return true
			}
		}
	}
	return false
}
